var e={brand:`ASTRAHUB`,product:`ASTRA STATION`},t=[],n=[`COMMANDER`,`FLIGHT ENGINEER`,`GEOLOGIST`,`MEDICAL OFFICER`,`SCIENTIST`,`MEDIA & COMMS`],r=[{n:0,title:`Prologue: The Path`,status:`now`,ru:`Путь к идее: экспедиции, горы и полевая геология.`},{n:1,title:`Idea`,status:`now`,ru:`Концепция, модель, игра-симулятор, 3D-модель и ролик «Before Mars».`},{n:2,title:`Partner Search`,status:`now`,ru:`Подготовка к встречам и форумам, презентации проекта.`},{n:3,title:`Site & Permits`,status:`planned`,ru:`Обследование плато Устюрт, выбор участка и согласования.`},{n:4,title:`Engineering`,status:`planned`,ru:`Инженеры, чертежи, выбор корпуса, расчёты жизнеобеспечения.`},{n:5,title:`Module Build`,status:`planned`,ru:`Сборка двух модулей Ø3,4 × 10 м, испытания на герметичность и воздух.`},{n:6,title:`Delivery & Assembly`,status:`planned`,ru:`Доставка в пустыню, установка, подключение энергии и воды.`},{n:7,title:`Systems Tests`,status:`planned`,ru:`Первые проверки систем, отказы и исправления.`},{n:8,title:`Crew`,status:`planned`,ru:`Отбор, подготовка, медицина и тренировки первого тестового экипажа.`},{n:9,title:`First Mission`,status:`planned`,ru:`7–10 дней в станции по режиму миссии, выходы в скафандрах, возможная пыльная буря.`},{n:10,title:`IAC 2028`,status:`goal`,ru:`Международный астронавтический конгресс, Самарканд, 9–13 октября 2028: цель — представить проект.`},{n:11,title:`ASTRO CITY`,status:`planned`,ru:`Город для гостей и для Каракалпакстана — следующий шаг после пилота.`}],i={tashkent:{id:`tashkent`,code:`STATION 01`,name:`TASHKENT`,tab:`Tashkent`,short:`Tashkent`,specs:[`7 × 10 m`,`~25 seats`,`Street level`],ru:`Проект первого этажа в центре Ташкента, рядом с Tashkent City Park. Фасад — модуль МКС, внутри прямой зал с баром, мини-кухней и тур-деском.`},astrocity:{id:`astrocity`,code:`STATION 02`,name:`ASTRO CITY`,tab:`ASTRO CITY`,short:`Astro`,specs:[`Dome Ø 11.3 m`,`~100 m²`,`~35 seats + terrace`],ru:`Проект на плато Устюрт (Каракалпакстан): купол у обрыва чинка, Island Bar, терраса с телескопом и пилотная станция из двух модулей для аналоговых миссий.`},konyukhov:{id:`konyukhov`,code:`STATION 03`,name:`N.KONYUKHOV`,tab:`N.KONYUKHOV`,short:`Konyukhov`,specs:[`2 trucks 4 × 2.4 m`,`Coffee around the world`,`Ski resort`],ru:`Мобильная кофейня премиум-класса на ГК «Солнечная долина»: бар и кухня в двух траках, лавки для экипировки, стойка для лыж, столы-бочки.`}},a={tashkent:{facade:{title:`Module Facade`,text:`Фасад — модуль МКС: композитные панели, иллюминаторы, кольца жёсткости. Ночью светится как капсула.`},entrance:{title:`Airlock Entrance`,text:`Вход-шлюз с автоматическими дверями. Оранжевая линия на полу ведёт прямо к бару.`},bar:{title:`Bar`,text:`Напитки MARS, LUNA, EARTH. 5 мест у стойки, витрина десертов, холодильники с напитками и мойка на задней линии.`},kitchen:{title:`Mini Kitchen`,text:`Мини-кухня за стеклом: холодильник, мойка, индукция и вытяжка с воздуховодом. Вход для персонала из-за бара.`},merch:{title:`Space & Merch`,text:`Маленькая витрина: кружки, нашивки миссий, модели ракет и капсул.`},tourdesk:{title:`Tour Desk`,text:`Здесь будет запись на туры в ASTRO CITY. На экране — дорожная карта проекта, на столе — макет купола Station 02.`},crew:{title:`Crew Wall`,text:`Стена Founding Crew: места первого тестового экипажа Mission 001. Имена появятся, когда участники согласятся.`},hall:{title:`Main Hall`,text:`Прямой зал 7 × 10 м, ~25 мест: 4 стола, стойка у иллюминаторов, бар.`},earth:{title:`Earth View`,text:`Иллюминаторы-экраны: живой вид на Землю с орбиты.`},park:{title:`Tashkent City Park`,text:`Через дорогу — парк Tashkent City и башни делового центра.`},restrooms:{title:`Restrooms`,text:`Два санузла за дверью между баром и тур-деском: WC 01 доступный для маломобильных гостей и WC 02. Раковины, сушилки, вытяжка.`},hvac:{title:`Ventilation`,text:`Решётки притока на торцах модуля, диффузоры в потолке зала, вытяжка из санузлов и кухни, блоки кондиционеров на крыше.`}},astrocity:{dome:{title:`Dome Ø 11.3 m`,text:`Геодезический купол: композитные панели и стеклянный сектор на закат и обрыв.`},corridor:{title:`Airlock Corridor`,text:`Длинный шлюз-коридор 12 м с иллюминаторами — переход с плато внутрь станции.`},bar:{title:`Island Bar`,text:`Круглый бар в центре купола, 8 мест. Напитки MARS, LUNA, EARTH.`},merch:{title:`Space & Merch`,text:`Витрина у стены купола: нашивки, кружки, модели ровера. Рядом — холодильник с напитками.`},tourdesk:{title:`Tour Desk`,text:`Стойка у входа: здесь будут экскурсии по ASTRO CITY, ночные наблюдения и поездки к чинку. На экране — план первой миссии.`},hall:{title:`Main Hall`,text:`~100 м², ~35 мест: столы по кругу и стойка у панорамного остекления.`},terrace:{title:`Terrace`,text:`Терраса над обрывом чинка: закат над Устюртом и звёздное небо.`},telescope:{title:`Telescope`,text:`Телескоп на террасе для ночных наблюдений: Луна, Сатурн, Млечный Путь.`},solar:{title:`Solar Field`,text:`Солнечное поле будет питать станцию: ряды панелей к востоку от купола.`},antenna:{title:`Antenna`,text:`Антенна связи и мачта с маяком — ориентир станции ночью.`},rover:{title:`ASTRA Rover`,text:`ASTRA Rover у входа — шестиколёсный ровер для выходов экипажа и поездок по плато.`},habitat:{title:`Pilot Station`,text:`Пилотная станция для аналоговых миссий: два модуля Ø3,4 × 10 м — жилой HAB и лаборатория LAB (планируется).`},hab:{title:`HAB Module`,text:`Жилой модуль: 4 спальных места, камбуз и стол экипажа, санузел. Миссия — 7–10 дней по режиму.`},lab:{title:`LAB Module`,text:`Лаборатория: рабочие места, панель систем жизнеобеспечения, стойка скафандров у шлюза.`},eva:{title:`EVA`,text:`Выход в скафандрах: экипаж идёт от шлюза пилотной станции к роверу.`},power:{title:`Power & Water`,text:`Энергоблок и баки воды: подключение энергии и воды — этап монтажа станции.`},gate:{title:`ASTRO CITY Gate`,text:`Указатели к воротам ASTRO CITY: дорога вдоль плато.`},restrooms:{title:`Restrooms`,text:`Сервисный модуль сбоку от шлюза: две раковины с зеркалами-иллюминаторами и два санузла (WC A доступный).`},hvac:{title:`HVAC`,text:`Наружные блоки вентиляции и кондиционирования: воздуховоды в купол и сервисный модуль, сопла под кольцевой балкой.`}},konyukhov:{truck:{title:`N.KONYUKHOV Trucks`,text:`Два фудтрака 4 × 2,4 м, соединённые в одну кофейню: слева бар, справа кухня. Брендирование под заказ.`},coffee:{title:`Coffee Around the World`,text:`Эфиопия, Турция, Вьетнам, Италия, Австралия, Колумбия, Аргентина — каждый напиток как авторская реконструкция местной традиции.`},kitchen:{title:`Kitchen Window`,text:`Пицца (5 видов), хот-доги, панини, венские вафли и панкейки, согревающие напитки и чай.`},tables:{title:`Barrel Tables`,text:`Столики-бочки без посадки: быстрый перекус между спусками.`},benches:{title:`Gear Benches`,text:`Лавки для ожидания и снятия экипировки.`},skirack:{title:`Ski & Board Rack`,text:`Стойка для лыж и сноубордов у площадки — оборудование под присмотром.`},heaters:{title:`Heaters & Lights`,text:`Уличные обогреватели и гирлянды: тёплая площадка днём и вечером.`},story:{title:`Founder Story`,text:`«Я пил кофе под снежными вершинами, в джунглях и на берегу океана. Каждая чашка — это история».`},lift:{title:`Chairlift`,text:`Кресельный подъёмник рядом с площадкой: поток гостей ГК «Солнечная долина» — около 350 000 человек за 2024 год.`},slope:{title:`Ski Runs`,text:`Трассы со склона спускаются прямо к кофейне; вечером — освещение для катания.`},bar:{title:`Bar`,text:`Кофемашина на 2 группы, кофемолки для эспрессо и фильтра, станция фильтра, холодильники для молока и напитков, мойка.`},galley:{title:`Galley`,text:`Комбинированная печь, панини-пресс, вафельница, гриль для панкейков, микроволновка, вытяжка, морозильная камера.`}}};export{i as a,r as i,t as n,a as o,e as r,n as t};